import {highlightHtml,evidencePreview} from './report-highlight.mjs';
import {sliceCp} from './engine.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('zh-CN');
const pct=n=>(n*100).toFixed(1);
const date=s=>new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const highlight=highlightHtml;
export function reportHtml(report){let evidenceBudget=120;const sourceMap=new Map(report.sources.map(source=>[source.id,source]));const evidenceRows=paragraph=>{const rows=evidencePreview(paragraph.matches,Math.min(12,evidenceBudget));evidenceBudget-=rows.length;return rows;};return `<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><title>${esc(report.title)} · PaperKnow</title><style>body{max-width:1000px;margin:40px auto;padding:0 24px;font:15px/1.9 system-ui,sans-serif;color:#22324c}h1,h2,h3{color:#152542}header{border-bottom:2px solid #286dff;padding-bottom:24px}.notice{background:#f0f6ff;padding:16px;border-radius:8px}.metrics{display:flex;gap:30px;flex-wrap:wrap;margin:24px 0}.metrics b{display:block;font-size:28px;color:#286dff}section{margin:26px 0}mark{background:#ffebd5;color:#994f20}.quoted{background:#e0f4ed;color:#237258}.excluded{color:#8c97aa}.evidence{border:1px solid #dce5f0;padding:16px;border-radius:8px;margin:15px 0}small{color:#789}p{white-space:pre-wrap}details{border-bottom:1px solid #dce5f0;padding:12px 0}a{color:#286dff}</style><header><p>PaperKnow / 学术论文查重</p><h1>${esc(report.title)}</h1><p>${date(report.createdAt)} · ${esc(report.id)} · ${esc(report.algorithm)}</p></header><p class="notice">本地材料比对报告，未检索在线学术数据库。本报告不包含语义分数、AI 率或外部数据库检测结果。不等同于知网、万方、维普检测。</p><div class="metrics"><div>总相似度<b>${pct(report.ratio)}%</b></div><div>去除识别引用后<b>${pct(report.uncitedRatio)}%</b></div><div>检测字数<b>${fmt(report.totalChars)}</b></div><div>相似字数<b>${fmt(report.similarChars)}</b></div><div>相似来源<b>${report.sourceCount}</b></div></div>${report.sections.map(s=>`<section class="${s.included?'':'excluded'}"><h2>${esc(s.title)} · ${s.included?pct(s.ratio)+'%':'未参与检测'}</h2>${s.paragraphs.map(p=>`<p>${s.included?highlight(p.text,p.matches):esc(p.text)}</p>${s.included&&p.matches.length?`<details><summary>查看 ${p.matches.length} 个匹配区间</summary><p class="notice">为便于阅读，每段最多展示 12 个代表区间，本文件最多展示 120 个；更多匹配保留在完整报告 JSON 中。正文高亮和上述指标仍按全部实际区间计算。</p>${evidenceRows(p).map(m=>{const source=sourceMap.get(m.sourceId);return `<div class="evidence"><h3>${esc(source.title)}</h3><small>${esc(source.authors?.join('、'))} · ${esc(source.year||'年份未提供')} · ${esc(source.provider)}</small><p>原文：${esc(sliceCp(p.text,...m.range))}</p><p>来源：${esc(sliceCp(source.text,...m.sourceRange))}</p><small>引用状态：${m.citationStatus==='verified_quotation'?'含已识别引用':'未识别引用'}；语义相似度：未接入</small></div>`;}).join('')}</details>`:''}`).join('')}</section>`).join('')}<section><h2>对照材料与来源信息</h2>${report.sources.map(s=>`<div class="evidence"><h3>${esc(s.title)}</h3><p>作者：${esc(s.authors?.join('、')||'未提供')} · 年份：${esc(s.year||'未提供')} · 来源：${esc(s.provider)}</p><p>DOI：${esc(s.doi||'未提供')}<br>URL：${esc(s.url||'未提供')}<br>材料类型：${s.kind==='demo'?'演示材料':'用户提供，未联网核验'}</p><p>${esc(s.text)}</p></div>`).join('')}</section><h2>计算说明</h2><p>匹配字符区间合并去重后计数，字数包含 Unicode 字母与数字，不含标点空白。语义相似不计入总分。引用排除规则：${esc(report.citationPolicy)}。TOP 来源比例存在重叠，不可相加。</p></html>`;}
